import ImageEditorField from './ImageEditorField';
import { ArrowDown, ArrowUp, Settings2, Trash2, Upload } from 'lucide-react';
import { Popover, PopoverContent, PopoverTrigger } from './ui/popover';
import type { ReactNode } from 'react';
import type { BookPage } from '@/lib/filmBooks';
const button='inline-flex min-h-11 items-center justify-center gap-1.5 rounded-md border border-ink/20 bg-paper px-3 text-sm hover:bg-ink/5 disabled:opacity-35';
export default function FilmPageHeader({page,number,sectionMenu,toneEnabled,update,illustration,importImage,watermark,importWatermark,up,down,remove,canUp,canDown,canRemove,insert}: {page:BookPage;number:number;sectionMenu:ReactNode;toneEnabled:boolean;update:(patch:Partial<BookPage>)=>void;watermark:()=>void;importWatermark:(file:File|undefined)=>void;illustration:()=>void;importImage:(file:File|undefined)=>void;up:()=>void;down:()=>void;remove:()=>void;canUp:boolean;canDown:boolean;canRemove:boolean;insert:()=>void}) {
  if(page.cover||page.frontMatter||page.generated||page.backCover)return <div data-film-page-header className="mb-2 text-sm font-semibold">{page.cover?"Couverture":page.generated==="toc"?"Sommaire":page.generated==="index"?"Index":page.backCover?"Quatri\u00e8me de couverture":"Page technique"}</div>;
  return <div data-film-page-header className="mb-2 flex w-[calc(100vw-6rem)] max-w-[210mm] sm:w-full flex-wrap items-center justify-between gap-2 rounded-lg border border-ink/15 bg-paper/90 p-2">
    <span className="px-1 text-sm font-semibold">{page.generated==='toc'?'Sommaire':page.generated==='index'?'Index':page.cover?'Couverture':page.titlePage?'Titre de section':`Page ${number} · ${number%2?'droite':'gauche'}`}</span>
    <div className="flex flex-wrap items-center gap-1.5">{sectionMenu}
      <Popover><PopoverTrigger asChild><button className={button} title="Options de la page" aria-label={`Options de la page ${number}`}><Settings2 size={18}/><span>Page</span></button></PopoverTrigger><PopoverContent collisionPadding={{top:72,bottom:88,left:12,right:12}} style={{maxHeight:"min(70vh, var(--radix-popover-content-available-height))",overflowY:"auto"}} role="dialog" aria-label={`Options de la page ${number}`} align="end" className="w-72 max-w-[calc(100vw-2rem)] space-y-3 bg-paper text-foreground"><h2 className="font-semibold">Options de la page {number}</h2>{!page.titlePage&&<label className="flex min-h-11 items-center gap-2 text-sm"><input type="checkbox" checked={!!page.imagePage} onChange={event=>update({imagePage:event.target.checked?{numberColor:"white"}:undefined})}/>Page image</label>}{page.imagePage&&<div className="space-y-3"><ImageEditorField label="Image de la page" inputLabel="Importer une image pleine page" value={page.imagePage.source} aspectRatio={210/297} maxImageDimension={2000} onChange={source=>update({imagePage:{...page.imagePage!,source}})}/><label className="block text-sm">Couleur du numéro<select aria-label="Couleur du numéro de page" value={page.imagePage.numberColor} onChange={event=>update({imagePage:{...page.imagePage!,numberColor:event.target.value as "white"|"black"}})} className="mt-1 min-h-11 w-full rounded border bg-paper px-2"><option value="white">Blanc</option><option value="black">Noir</option></select></label></div>}{!page.imagePage&&<>{!page.titlePage&&<label className="block text-sm">Variante du fond<select aria-label={`Variante du fond page ${number}`} disabled={!toneEnabled} value={page.backgroundTone??'default'} className="mt-1 h-10 w-full rounded border border-ink/20 bg-paper px-2" onChange={e=>update({backgroundTone:e.target.value==='default'?undefined:e.target.value as 'light'|'dark'})}><option value="default">Réglage de la section</option><option value="light">Claire</option><option value="dark">Sombre</option></select></label>}
      <button className={`${button} w-full`} disabled={!!page.generated} onClick={illustration}>Image depuis les ressources</button>{!page.titlePage&&!page.imagePage&&<fieldset className="space-y-3 border-t border-ink/15 pt-3"><legend>Image en filigrane</legend><button className={button} onClick={watermark}>Depuis les ressources</button><label className={button}>Depuis l’ordinateur<input aria-label="Importer un filigrane" type="file" className="hidden" accept="image/png,image/jpeg,image/webp" onChange={e=>{importWatermark(e.target.files?.[0]);e.target.value="";}}/></label>{page.watermark&&<><label className="block text-sm">Opacité : {Math.round(page.watermark.opacity*100)} %<input aria-label="Opacité du filigrane" className="block w-full" type="range" min="0" max="100" value={Math.round(page.watermark.opacity*100)} onChange={e=>update({watermark:{...page.watermark!,opacity:Number(e.target.value)/100}})}/></label><label className="block text-sm">Taille : {page.watermark.size} %<input aria-label="Taille du filigrane" className="block w-full" type="range" min="10" max="200" value={page.watermark.size} onChange={e=>update({watermark:{...page.watermark!,size:Number(e.target.value)}})}/></label><label className="block text-sm">Estompage des bords : {page.watermark.featherMm??10} mm<input aria-label="Estompage du filigrane" className="block w-full" type="range" min="1" max="25" step="0.5" value={page.watermark.featherMm??10} onChange={e=>update({watermark:{...page.watermark!,featherMm:Number(e.target.value)}})}/></label>{(['x','y'] as const).map(axis=><label key={axis} className="block text-sm">{axis==='x'?'Position horizontale':'Position verticale'} : {page.watermark?.[axis]??50} %<input aria-label={axis==='x'?'Position horizontale du filigrane':'Position verticale du filigrane'} className="block w-full" type="range" min="-50" max="150" value={page.watermark?.[axis]??50} onChange={e=>update({watermark:{...page.watermark!,[axis]:Number(e.target.value)}})}/></label>)}<button className={button} onClick={()=>update({watermark:{...page.watermark!,x:50,y:50}})}>Recentrer le filigrane</button><button className={button} onClick={()=>update({watermark:undefined})}>Supprimer le filigrane</button></>}</fieldset>}<label className={`${button} w-full cursor-pointer`}><Upload size={16}/>Image depuis l’ordinateur<input aria-label={`Importer une illustration page ${number}`} disabled={!!page.generated} type="file" className="hidden" accept="image/png,image/jpeg,image/webp" onChange={e=>{importImage(e.target.files?.[0]);e.target.value='';}}/></label></>}<div className="flex gap-2 border-t border-ink/10 pt-3"><button className={`${button} flex-1`} disabled={!canUp} onClick={up}><ArrowUp size={16}/>Monter</button><button className={`${button} flex-1`} disabled={!canDown} onClick={down}><ArrowDown size={16}/>Descendre</button></div><button className={`${button} w-full text-destructive`} disabled={!canRemove} onClick={remove}><Trash2 size={16}/>Supprimer la page</button></PopoverContent></Popover>
    </div>
  </div>;
}
